"""Generates docs/product/permission-matrix.md from the code-defined catalogue (run from repo root)."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "apps" / "api"))
from app.modules.tenancy.permissions import CATALOG, DEFAULT_ROLES  # noqa: E402

roles = list(DEFAULT_ROLES)
lines = [
    "# Permission Matrix",
    "",
    "_Generated by `scripts/gen_permission_matrix.py` from `apps/api/app/modules/tenancy/permissions.py`. Do not edit by hand._",
    "",
    "Platform Super Admin is not a tenant role (`identities.is_platform_admin`) and holds no tenant data permissions.",
    "Sensitive permissions are marked **S**.",
    "",
    "| Permission | S | " + " | ".join(DEFAULT_ROLES[r][0] for r in roles) + " |",
    "|---|---|" + "---|" * len(roles),
]
for code, (_, _, sens) in sorted(CATALOG.items()):
    cells = " | ".join("✓" if code in DEFAULT_ROLES[r][2] else "" for r in roles)
    lines.append(f"| `{code}` | {'S' if sens else ''} | {cells} |")
out = ROOT / "docs" / "product" / "permission-matrix.md"
out.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {out}")
